import{_ as l,a0 as a,w as p,s as g,I as r,x as o,a1 as i,A as e,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"Spritz 12 年前融資 350 萬做快速閲讀，今天這事歸 AI 管了 | LCTT x X-CMD","titleTemplate":false,"description":"2014 年 Spritz 這家「RSVP 快速閲讀」公司融了 350 萬美元種子輪，TechCrunch 報道後 ReadWrite 整理了 Linux 上 4 個快速閲讀工具。12 年後看，Spritz 倒閉，RSVP 被 AI 摘要徹底取代。","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Spritz 12 年前融資 350 萬做快速閲讀，今天這事歸 AI 管了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2014 年 Spritz 這家「RSVP 快速閲讀」公司融了 350 萬美元種子輪，TechCrunch 報道後 ReadWrite 整理了 Linux 上 4 個快速閲讀工具。12 年後看，Spritz 倒閉，RSVP 被 AI 摘要徹底取代。"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to speed read on Linux","title":"Spritz 12 年前融資 350 萬做快速閲讀，今天這事歸 AI 管了","tag":"201405","desc":"2014 年 Spritz 這家「RSVP 快速閲讀」公司融了 350 萬美元種子輪，TechCrunch 報道後 ReadWrite 整理了 Linux 上 4 個快速閲讀工具。12 年後看，Spritz 倒閉，RSVP 被 AI 摘要徹底取代。"},"relativePath":"201405/How to speed read on Linux.md","filePath":"[post].md"}'),S={name:"201405/How to speed read on Linux.md"};function d(u,t,P,m,T,A){const n=a("Link");return p(),g("div",null,[t[13]||(t[13]=r("h1",{id:"spritz-12-年前融資-350-萬做快速閲讀-今天這事歸-ai-管了",tabindex:"-1"},[o("Spritz 12 年前融資 350 萬做快速閲讀，今天這事歸 AI 管了 "),r("a",{class:"header-anchor",href:"#spritz-12-年前融資-350-萬做快速閲讀-今天這事歸-ai-管了","aria-label":"Permalink to “Spritz 12 年前融資 350 萬做快速閲讀，今天這事歸 AI 管了”"},"​")],-1)),r("blockquote",null,[r("p",null,[t[1]||(t[1]=o("老文新評 #032 · ",-1)),i(n,{href:"http://techcrunch.com/2014/03/10/spritz-seed/",rel:"nofollow noopener"},{default:e(()=>[...t[0]||(t[0]=[o("techcrunch.com",-1)])]),_:1}),t[2]||(t[2]=o(" · 2014-05-01",-1))])]),t[14]||(t[14]=s('<h2 id="一句話總結" tabindex="-1">一句話總結 <a class="header-anchor" href="#一句話總結" aria-label="Permalink to “一句話總結”">​</a></h2><p>Spritz 12 年前想做「讓你讀得更快」的工具——今天 AI 直接「替你讀完」，RSVP 這個品類徹底消失，Spread0r、Chrome Spread、書籤 Squirt、開源 Zethos 全進了開源墓園。</p><h2 id="文章講了啥" tabindex="-1">文章講了啥 <a class="header-anchor" href="#文章講了啥" aria-label="Permalink to “文章講了啥”">​</a></h2><p>2014 年 3 月，Spritz 這家波士頓公司融了 350 萬美元種子輪，做 RSVP（rapid serial visual presentation）快速閲讀 API——把單詞一個接一個釘在屏幕的同一個位置，讓眼球不再移動，被吹捧為「閲讀的未來」。TechCrunch 報道後，ReadWrite 順勢整理了 Linux 上 4 個快速閲讀工具：</p><ul><li><strong>Spread0r</strong> —— Perl + GTK2 寫的 GPL 軟件，原名 Gritz，從 GitHub 拉源碼運行，最高 1000 詞/分</li><li><strong>Spread</strong> —— Chrome 瀏覽器擴展，選中網頁文本右鍵「Spreed selected text」，可在新窗口裏 RSVP 閲讀，速度最高 4000 詞/分</li><li><strong>Squirt</strong> —— 書籤欄小工具（非擴展），點擊後在當前頁彈出白色面板閲讀，UI 漂亮，速度上限 4000+ 詞/分</li><li><strong>Zethos</strong> —— 開源 JavaScript 項目，給開發者自己 fork 出 RSVP 應用的起點</li></ul><p>這 4 個工具的共同點是「單詞一個一個出現」——讓眼睛不再左右移動。文章最後吐槽「小心你的大腦別被燒焦」——12 年後這反而成了最準確的隱喻。</p><h2 id="_12-年後重讀" tabindex="-1">12 年後重讀 <a class="header-anchor" href="#_12-年後重讀" aria-label="Permalink to “12 年後重讀”">​</a></h2><p>12 年後再看 Spritz 這條線，<strong>最諷刺的是它被自己的「目標用户」淘汰</strong>。Spritz 想讓人「讀得更快」，但 2026 年的解決方案不是讓人讀得更快，而是<strong>讓 AI 替人讀完</strong>。GPT-4 / Claude 3 / Gemini 都能在 5 秒內讀完一篇 5000 字長文並生成 200 字摘要，附帶 5 個核心觀點和待追問問題。</p><p>這背後的範式轉換很有意思：</p><ul><li><strong>RSVP</strong> 是「加速人的閲讀速度」——人還是主導</li><li><strong>AI 摘要</strong> 則是「跳過人的閲讀」——人退到提問者位置</li></ul><p>Spread0r 這種 2014 年工具的「亮點」是「1000 詞/分」；2026 年的 AI 是「10000 字/秒」，且能回答「這段在説什麼」。兩種方案的目標都是「高效獲取信息」，但 AI 路徑根本不讓人讀。</p><p><strong>更值得玩味的是「注意力經濟」這條線</strong>。Spritz 當年押注的「注意力稀缺」——12 年後注意力確實變成了稀缺資源，但解決方案不是 RSVP，而是<strong>TikTok 短視頻</strong>。</p><p>一分鐘一個視頻、三秒一個鈎子——這種節奏感反而和 Spritz 那種「一個詞接一個詞」有異曲同工之妙。區別是：RSVP 想保留「讀完」的成就感，TikTok 索性把「讀完」這件事整個消解了。</p><p><strong>Spread0r / Spritz 這種工具的真正繼承者</strong>——是 NotebookLM 這種「AI 給你讀」的方案。NotebookLM 把你的筆記、PDF、網頁轉成播客式對話，讓兩個 AI「討論」內容給你聽。這不是 RSVP（讓你讀），也不是純文本摘要（讓你看），是 <strong>AI 替你和替我討論——你只負責聽和追問</strong>。</p><p><strong>12 年間「讀」這件事的 3 個階段</strong>：</p><ul><li><strong>2014</strong>：人 + 工具（RSVP）—— 讓眼睛動得少</li><li><strong>2020</strong>：人 + 工具（語音合成 + 音頻）—— 讓眼睛不用動</li><li><strong>2026</strong>：AI + AI（NotebookLM、AI 播客）—— 讓人根本不用讀</li></ul><p><strong>Spritz 當年犯的根本錯誤</strong>是：他們想解決「人讀得慢」，但沒意識到「人為什麼要讀」這個問題本身正在被 AI 替代。<strong>「快速閲讀」的真正答案不是「讀得快」，是「不用讀」</strong>。</p><h2 id="那個被-spritz-漏掉的「注意力流向」" tabindex="-1">那個被 Spritz 漏掉的「注意力流向」 <a class="header-anchor" href="#那個被-spritz-漏掉的「注意力流向」" aria-label="Permalink to “那個被 Spritz 漏掉的「注意力流向」”">​</a></h2><p>回看 2014 年 Spritz 的整套邏輯——把單詞釘在屏幕中央讓眼睛不移動，節省眼球運動時間——<strong>這套設計的潛台詞是「閲讀是眼睛的體力活」</strong>。</p><p>12 年後回看，這個潛台詞完全錯。<strong>閲讀從來不是眼睛的體力活，是大腦的認知活</strong>。RSVP 節省的那點眼球運動時間，對真正難懂的內容（論文、法律文書、代碼）來説根本不是瓶頸——<strong>理解才是瓶頸</strong>。Spritz 讓你 5 分鐘掃完 5000 字，但你可能根本沒懂它在説什麼。</p><p><strong>更諷刺的是 Spritz 當年的「小心大腦被燒焦」警告</strong>——12 年後這反而成了最準確的預言：</p><ul><li><strong>Saccade（眼動）減少</strong> → 失去深度閲讀能力</li><li><strong>碎片化閲讀</strong> → 注意力只能維持 30 秒</li><li><strong>跳讀（skimming）訓練</strong> → 讀完整本書的能力下降</li></ul><p>2026 年的研究（Common Sense Media、Pew Research、Microsoft Attention Spans 報告）反覆發現：<strong>習慣 RSVP / 短視頻 / TL;DR 摘要的人，深度閲讀能力顯著下降</strong>。這反而是 RSVP 範式的真正遺產——它<strong>訓練了一代不會深度閲讀的人</strong>。</p><p><strong>Spritz 真正的繼承者不是「讀得更快」的工具，而是「幫用户判斷值不值得讀」的工具</strong>：</p><ul><li>Pocket / Matter —— 稍後讀（但變成「永不讀」）</li><li>Readwise Reader —— 強調深度閲讀和筆記</li><li>NotebookLM —— 替用户讀 + 總結</li><li>AI 閲讀助手（ChatGPT Read、Claude Connectors）—— 邊讀邊問</li></ul><p><strong>12 年前 Spritz 的目標</strong>「讓你 5 分鐘讀完一篇文章」——<strong>12 年後被 AI 實現得過於完美</strong>。一篇 5000 字的長文，AI 5 秒就能總結成 200 字 + 5 個觀點 + 3 個待追問問題。<strong>代價是：人不再深度閲讀了</strong>。</p><p>Spritz 當年那個 RSVP 想法本身不算錯——但<strong>他沒意識到自己是在和「AI 摘要」這條更根本的解決方案賽跑</strong>。2014 年 AI 還沒成熟，Spritz 拿到了 350 萬美元種子輪；2017 年 Spritz 倒閉，被 Samsung 收購後無疾而終；2026 年 RSVP 這個品類徹底消失——<strong>「讀得快」這件事，被「不用讀」徹底替代</strong>。</p><hr><p><strong>出處</strong></p>',29)),r("ul",null,[r("li",null,[t[4]||(t[4]=r("strong",null,"原文",-1)),t[5]||(t[5]=o("（ARR 風險）：",-1)),i(n,{href:"http://techcrunch.com/2014/03/10/spritz-seed/",rel:"nofollow noopener"},{default:e(()=>[...t[3]||(t[3]=[o("techcrunch.com",-1)])]),_:1})]),r("li",null,[t[7]||(t[7]=r("strong",null,"LCTT 譯稿源檔",-1)),t[8]||(t[8]=o("：",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject/blob/master/sources/tech/"},{default:e(()=>[...t[6]||(t[6]=[o("github.com/LCTT/TranslateProject",-1)])]),_:1})]),r("li",null,[t[10]||(t[10]=r("strong",null,"原譯",-1)),t[11]||(t[11]=o("：",-1)),i(n,{href:"https://lctt.x-cmd.com/201405/How%20to%20speed%20read%20on%20Linux/"},{default:e(()=>[...t[9]||(t[9]=[o("linux.cn",-1)])]),_:1})]),t[12]||(t[12]=r("li",null,[r("strong",null,"發佈"),o("：2014-05-01")],-1))]),t[15]||(t[15]=s('<hr><h2 id="這些觀點今天還成立嗎" tabindex="-1">這些觀點今天還成立嗎？ <a class="header-anchor" href="#這些觀點今天還成立嗎" aria-label="Permalink to “這些觀點今天還成立嗎？”">​</a></h2><ul><li>❌ <strong>RSVP 是提升閲讀速度的方案</strong> —— 已被 AI 摘要替代，沒人再用 RSVP 工具</li><li>❌ <strong>Spritz 是這條賽道的領跑者</strong> —— Spritz 2017 年倒閉，被 Samsung 收購後無疾而終</li><li>⚠️ <strong>最高 1000-4000 詞/分是目標</strong> —— 現在 AI 1 秒讀 1 萬字，提問還能繼續追問</li><li>⚠️ <strong>極客願意為生產力工具付費</strong> —— 仍成立，但訂閲制 + AI 增值是主流</li><li>⚠️ <strong>移動設備需要「快速閲讀」</strong> —— 移動設備的解決方案變成音頻（Audible / 播客）+ AI 摘要</li><li>⚠️ <strong>注意力經濟會被工具改進</strong> —— 注意力經濟反而被短視頻 / TikTok 改造得更碎片</li></ul>',3))])}const R=l(S,[["render",d]]);export{I as __pageData,R as default};
